import "jsr:@supabase/functions-js/edge-runtime.d.ts";

type Scenario = "NORMAL"|"COMPETITION"|"TRAFFIC_COST"|"LOW_CVR"|"PRICE_WAR"|"LOW_STOCK"|"CASH_TIGHT"|"DEMAND_SURGE";

function simulate(rounds:number, scenario:Scenario) {
  const factor:Record<Scenario,number>={NORMAL:1,COMPETITION:.85,TRAFFIC_COST:.75,LOW_CVR:.65,PRICE_WAR:.92,LOW_STOCK:1,CASH_TIGHT:1,DEMAND_SURGE:1.15};
  let stock=scenario==="LOW_STOCK"?108:600, cash=scenario==="CASH_TIGHT"?7668:42600;
  let spend=0,revenue=0,conversions=0,blocked=0,learning=0,cal=0;
  const path:any[]=[];
  for(let i=1;i<=rounds;i++){
    const action=scenario==="TRAFFIC_COST"||scenario==="LOW_CVR"?(i%3===0?"DECREASE_BUDGET":"HOLD"):scenario==="DEMAND_SURGE"&&i%3===0?"INCREASE_BUDGET":scenario==="PRICE_WAR"&&i%4===0?"CHANGE_PRICE":i%5===0?"CHANGE_TARGETING":"HOLD";
    const approved=!(action==="INCREASE_BUDGET"&&i%7===0); if(action!=="HOLD"&&!approved) blocked++;
    const pressure=scenario==="TRAFFIC_COST"?1.45:scenario==="COMPETITION"?1.15:1;
    const s=Math.min(120,100/pressure+(i*17%20));
    const conv=Math.min(stock,Math.floor((s/pressure)*.04*factor[scenario]*(scenario==="DEMAND_SURGE"?1.25:1)));
    const price=89*(scenario==="PRICE_WAR"&&action==="CHANGE_PRICE"?.98:1);
    const rev=conv*price, roi=s?rev/s:0;
    stock=Math.max(0,stock-conv); cash=Math.max(0,cash-s+conv*28.5); spend+=s; revenue+=rev; conversions+=conv;
    if(s>0&&conv>0) learning++;
    const expected=3*factor[scenario]; cal+=Math.abs(expected-roi);
    path.push({round:i,action,approved,roi,stock,cash,opponent:scenario==="PRICE_WAR"?"PRICE_WAR":scenario==="TRAFFIC_COST"?"TRAFFIC_DEFENSE":"HOLD",breakthrough:roi>=expected?"ECONOMIC_GAP":scenario==="LOW_CVR"?"CONVERSION_GAP":scenario==="TRAFFIC_COST"?"TRAFFIC_GAP":"NO_CLEAR_GAP"});
  }
  return {scenario,rounds,totalSpend:spend,totalRevenue:revenue,totalConversions:conversions,finalRoi:spend?revenue/spend:0,finalStock:stock,finalCash:cash,blockedActions:blocked,learningSignals:learning,averageCalibrationError:cal/rounds,path:path.slice(-10)};
}
function cors(){return {"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, x-client-info, apikey, content-type","Access-Control-Allow-Methods":"POST, OPTIONS"};}
export default { fetch: async (req:Request) => {
  if(req.method==="OPTIONS") return new Response("ok",{headers:cors()});
  try {
    const body=await req.json().catch(()=>({}));
    const rounds=Math.min(100,Math.max(1,Number(body.rounds)||30));
    const scenarios:Scenario[]=Array.isArray(body.scenarios)&&body.scenarios.length?body.scenarios:["NORMAL","COMPETITION","TRAFFIC_COST","LOW_CVR","PRICE_WAR","LOW_STOCK","CASH_TIGHT","DEMAND_SURGE"];
    const results=scenarios.map(s=>simulate(rounds,s));
    return new Response(JSON.stringify({mode:"SANDBOX",rounds,scenarios:results}),{headers:{...cors(),"Content-Type":"application/json"}});
  } catch(e){return new Response(JSON.stringify({error:String(e)}),{status:400,headers:{...cors(),"Content-Type":"application/json"}});}
}};
